/**
 * Page: font-library (zc-admin integrated)
 * Auto-generated by build process.
 * Do not edit this file manually.
 *
 * This version integrates with the standard ZelocoreCMS admin interface,
 * keeping the zc-admin sidebar and scripts/styles intact.
 *
 * @package wp
 */

// Global storage for font-library routes and menu items
global $zc_font_library_zc_admin_routes, $zc_font_library_zc_admin_menu_items;
$zc_font_library_zc_admin_routes     = array();
$zc_font_library_zc_admin_menu_items = array();

/**
 * Register a route for the font-library-zc-admin page.
 *
 * @param string      $path           Route path (e.g., '/types/$type/edit/$id').
 * @param string|null $content_module Script module ID for content (stage/inspector).
 * @param string|null $route_module   Script module ID for route lifecycle hooks.
 */
function zc_register_font_library_zc_admin_route( $path, $content_module = null, $route_module = null ) {
	global $zc_font_library_zc_admin_routes;

	$route = array( 'path' => $path );
	if ( ! empty( $content_module ) ) {
		$route['content_module'] = $content_module;
	}
	if ( ! empty( $route_module ) ) {
		$route['route_module'] = $route_module;
	}

	$zc_font_library_zc_admin_routes[] = $route;
}

/**
 * Register a menu item for the font-library-zc-admin page.
 * Note: Menu items are registered but not displayed in single-page mode.
 *
 * @param string $id        Menu item ID.
 * @param string $label     Display label.
 * @param string $to        Route path to navigate to.
 * @param string $parent_id Optional. Parent menu item ID.
 */
function zc_register_font_library_zc_admin_menu_item( $id, $label, $to, $parent_id = '' ) {
	global $zc_font_library_zc_admin_menu_items;

	$menu_item = array(
		'id'    => $id,
		'label' => $label,
		'to'    => $to,
	);

	if ( ! empty( $parent_id ) ) {
		$menu_item['parent'] = $parent_id;
	}

	$zc_font_library_zc_admin_menu_items[] = $menu_item;
}

/**
 * Get all registered routes for the font-library-zc-admin page.
 *
 * @return array Array of route objects.
 */
function zc_get_font_library_zc_admin_routes() {
	global $zc_font_library_zc_admin_routes;
	return $zc_font_library_zc_admin_routes ?? array();
}

/**
 * Get all registered menu items for the font-library-zc-admin page.
 *
 * @return array Array of menu item objects.
 */
function zc_get_font_library_zc_admin_menu_items() {
	global $zc_font_library_zc_admin_menu_items;
	return $zc_font_library_zc_admin_menu_items ?? array();
}

/**
 * Preload REST API data for the font-library-zc-admin page.
 * Automatically called during page rendering.
 */
function zc_font_library_zc_admin_preload_data() {
	// Define paths to preload - same for all pages
	// Please also change packages/core-data/src/entities.js when changing this.
	$preload_paths = array(
		'/?_fields=description,gmt_offset,home,image_sizes,image_size_threshold,image_output_formats,jpeg_interlaced,png_interlaced,gif_interlaced,name,site_icon,site_icon_url,site_logo,timezone_string,url,page_for_posts,page_on_front,show_on_front',
		array( '/wp/v2/settings', 'OPTIONS' ),
	);

	// Use rest_preload_api_request to gather the preloaded data
	$preload_data = array_reduce(
		$preload_paths,
		'rest_preload_api_request',
		array()
	);

	// Register the preloading middleware with zc-api-fetch
	zc_add_inline_script(
		'zc-api-fetch',
		sprintf(
			'wp.apiFetch.use( wp.apiFetch.createPreloadingMiddleware( %s ) );',
			zc_json_encode( $preload_data )
		),
		'after'
	);
}

/**
 * Enqueue scripts and styles for the font-library-zc-admin page.
 * Hooked to admin_enqueue_scripts.
 *
 * @param string $hook_suffix The current admin page.
 */
function zc_font_library_zc_admin_enqueue_scripts( $hook_suffix ) {
	// Check all possible ways this page can be accessed:
	// 1. Menu page via admin.php?page=font-library-zc-admin (plugin)
	// 2. Direct file via font-library.php (Core) - screen ID will be 'font-library'
	$current_screen = get_current_screen();
	$is_our_page = (
		( isset( $_GET['page'] ) && 'font-library-zc-admin' === $_GET['page'] ) || // phpcs:ignore ZelocoreCMS.Security.NonceVerification.Recommended
		( $current_screen && 'font-library' === $current_screen->id )
	);

	if ( ! $is_our_page ) {
		return;
	}

	// Load build constants
	$build_constants = require __DIR__ . '/../../constants.php';

	// Fire init action for extensions to register routes and menu items
	do_action( 'font-library-zc-admin_init' );

	// Preload REST API data
	zc_font_library_zc_admin_preload_data();

	// Get all registered routes
	$routes = zc_get_font_library_zc_admin_routes();

	// Get boot module asset file for dependencies
	$asset_file = ABSPATH . WPINC . '/js/dist/script-modules/boot/index.min.asset.php';
	if ( file_exists( $asset_file ) ) {
		$asset = require $asset_file;

		// This script serves two purposes:
		// 1. It ensures all the globals that are made available to the modules are loaded.
		// 2. It initializes the boot module as an inline script.
		zc_register_script( 'font-library-zc-admin-prerequisites', '', $asset['dependencies'], $asset['version'], true );

		/*
		 * Add inline script to initialize the app using initSinglePage (no menuItems).
		 * The dynamic import is deferred until DOMContentLoaded so that all classic
		 * script dependencies of @zelocorecms/boot (zc-private-apis, zc-components,
		 * zc-theme, etc.) have finished parsing and executing before the boot module
		 * evaluates. Otherwise, a modulepreloaded @zelocorecms/boot can win the race
		 * against the classic-script-printing pass on fast CDN-fronted hosts in
		 * Chrome, evaluating before wp.theme.privateApis is defined and throwing
		 * "Cannot unlock an undefined object". See <https://core.trac.zelocorecms.org/ticket/65103>.
		 */
		$init_js_function = <<<'JS'
		( mountId, routes ) => {
			const run = async () => {
				const mod = await import( "@zelocorecms/boot" );
				mod.initSinglePage( { mountId, routes } );
			};
			if ( document.readyState === "loading" ) {
				document.addEventListener( "DOMContentLoaded", run );
			} else {
				run();
			}
		}
		JS;
		zc_add_inline_script(
			'font-library-zc-admin-prerequisites',
			sprintf(
				'( %s )( %s, %s );',
				$init_js_function,
				zc_json_encode( 'font-library-zc-admin-app', JSON_HEX_TAG | JSON_UNESCAPED_SLASHES ),
				zc_json_encode( $routes, JSON_HEX_TAG | JSON_UNESCAPED_SLASHES )
			)
		);

		// Register prerequisites style by filtering script dependencies to find registered styles
		$style_dependencies = array_filter(
			$asset['dependencies'],
			function ( $handle ) {
				return zc_style_is( $handle, 'registered' );
			}
		);
		zc_register_style( 'font-library-zc-admin-prerequisites', false, $style_dependencies, $asset['version'] );

		// Build dependencies for font-library-zc-admin module
		$boot_dependencies = array(
			array(
				'import' => 'static',
				'id'     => '@zelocorecms/boot',
			),
		);

		// Add all registered routes as dependencies
		foreach ( $routes as $route ) {
			if ( isset( $route['route_module'] ) ) {
				$boot_dependencies[] = array(
					'import' => 'static',
					'id'     => $route['route_module'],
				);
			}
			if ( isset( $route['content_module'] ) ) {
				$boot_dependencies[] = array(
					'import' => 'dynamic',
					'id'     => $route['content_module'],
				);
			}
		}

		// Dummy script module to ensure dependencies are loaded
		zc_register_script_module(
			'font-library-zc-admin',
			$build_constants['build_url'] . 'pages/font-library/loader.js',
			$boot_dependencies
		);

		// Enqueue the boot scripts and styles
		zc_enqueue_script( 'font-library-zc-admin-prerequisites' );
		zc_enqueue_script_module( 'font-library-zc-admin' );
		zc_enqueue_style( 'font-library-zc-admin-prerequisites' );
	}
}

/**
 * Render the font-library-zc-admin page.
 * Call this function from add_menu_page or add_submenu_page.
 * This renders within the normal ZelocoreCMS admin interface.
 */
function zc_font_library_zc_admin_render_page() {
	?>
	<style>
		/* Critical styles to prevent layout shifts - inlined for immediate application */

		#wpwrap {
			overflow-y: auto;
		}
		body {
			background: #fff;
		}

		/* Reset zc-admin padding */
		#wpcontent {
			padding-inline-start: 0;
		}
		#wpbody-content {
			padding-bottom: 0;
		}

		/* Hide legacy admin elements */
		#wpbody-content > div:not(.boot-layout-container):not(#screen-meta) {
			display: none;
		}
		#wpfooter {
			display: none;
		}

		/* Accessibility regions */
		.a11y-speak-region {
			inset-inline-start: -1px;
			top: -1px;
		}

		/* Admin menu indicators */
		ul#adminmenu a.zc-has-current-submenu::after,
		ul#adminmenu > li.current > a.current::after {
			border-inline-end-color: #fff;
		}

		/* Media frame fix */
		.media-frame select.attachment-filters:last-of-type {
			width: auto;
			max-width: 100%;
		}

		/* Responsive overflow fix for #wpwrap */
		@media (min-width: 782px) {
			#wpwrap {
				overflow-y: initial;
			}
		}
	</style>
	<div id="font-library-zc-admin-app" class="boot-layout-container"></div>
	<?php
}

// Hook the enqueue function to admin_enqueue_scripts
add_action( 'admin_enqueue_scripts', 'zc_font_library_zc_admin_enqueue_scripts' );

